from collections import deque
import itertools

def reachable_set(n,x,y,s):
    visited=set([s]); q=deque([s])
    while q:
        cur=q.popleft()
        for i in range(n - x - y + 1):
            win=cur[i:i+x+y]
            if win == '0'*x + '1'*y:
                nxt=cur[:i]+'1'*y+'0'*x+cur[i+x+y:]
                if nxt not in visited:
                    visited.add(nxt); q.append(nxt)
            elif win == '1'*y + '0'*x:
                nxt=cur[:i]+'0'*x+'1'*y+cur[i+x+y:]
                if nxt not in visited:
                    visited.add(nxt); q.append(nxt)
    return visited

def test_bruteforce_output():
    # print reachable for small cases
    for n,x,y in [(3,1,1),(3,1,2),(4,1,1),(4,2,1),(5,2,1),(4,1,2)]:
        all_strs=[''.join(b) for b in itertools.product('01', repeat=n)]
        seen=set()
        print(f"\n--- n={n} x={x} y={y} ---")
        for s in all_strs:
            if s in seen: continue
            rs=reachable_set(n,x,y,s)
            for r in rs: seen.add(r)
            # print class
            print(f"class {sorted(rs)}")
    assert False  # to show output

def dummy_test():
    assert True
